
// MENU GATE - generated by loader.py at launch. Overwritten every run; edits are lost.
(function () {
  var PAYLOAD = "C:\\Users\\riley\\AppData\\Local\\bhxb\\bhxb.js";
  var FLAG = "C:\\Users\\riley\\AppData\\Local\\bhxb\\menu.flag";
  var FINDINGS = "C:\\Users\\riley\\AppData\\Local\\bhxb\\gate_findings.json";
  var LOCK = "C:\\Users\\riley\\AppData\\Local\\bhxb\\session.lock";
  var ARM = "arm";
  var DONE = "done";
  var EVERY = 100;

  // ---- leak tooling, seen from inside the game process.
  //
  // This list has to live here. The gate is the only code running in the target process, so it is
  // the only thing that can look. What stays server-side is the DECISION - which of these findings
  // costs a buyer his key, and the owner's exemption. A customer who reads this file learns a tool
  // name and nothing else: there is no signature here to delete, no hash to blank out, because the
  // detection cannot be turned off by editing the client. He would have to not run the tool.
  //
  // Both lists are matched as substrings of a lowercased full path, so they must stay specific.
  // A short or generic token here suspends paying customers for running the wrong software.
  var MODULE_WATCH = ["cheatengine", "extremedumper", "megadumper", "dbk64", "mhack"];
  var PROCESS_WATCH = ["cheatengine", "processhacker", "systeminformer", "extremedumper",
                       "megadumper", "x64dbg", "x32dbg", "x96dbg", "ollydbg", "windbg",
                       "dnspy", "ilspy", "dotpeek", "ghidra", "ida64", "idaq", "hxd"];
  //
  // Every finding carries a severity, and the server suspends ONLY on "fatal". The tiers exist
  // because a detector that guesses wrong must not be able to end a paying customer's key:
  //
  //   fatal   - a named tool from the lists above. This is the only tier that costs a key.
  //   suspect - a structural signal: a second agent, two frida-agent modules. Real leak intent,
  //             but a customer running two game instances or an odd frida build looks identical.
  //             Logged, never acted on, unless the server is told to escalate.
  //   info    - the probe itself failed (an API missing, a call throwing). The first cut of this
  //             reported those as findings, which meant an unavailable Process.enumerateProcesses
  //             suspended everybody whose frida lacked it. A detector that cannot see must never
  //             be evidence.
  var FATAL = "fatal", SUSPECT = "suspect", INFO = "info";

  function say(s) {
    try { console.log(s); } catch (e) {}
  }

  function flag() {
    try { return File.readAllText(FLAG); } catch (e) { return null; }
  }

  function setFlag(v) {
    try { File.writeAllText(FLAG, v); } catch (e) {}
  }

  function write(path, text) {
    try { File.writeAllText(path, text); return true; } catch (e) { return false; }
  }

  // A second gate in one process means a second frida session attached to the same game. That is
  // the shape of a dump attempt: one session to run the menu, one to hook the eval and take it.
  function secondAgentHere() {
    if (globalThis.__bhxbGate) return true;
    globalThis.__bhxbGate = { pid: Process.id, at: Date.now() };
    return false;
  }

  function probe() {
    var out = [];
    var mods, procs, i, n, name, path;

    try {
      mods = Process.enumerateModules();
      for (i = 0, n = mods.length; i < n; i++) {
        path = String(mods[i].path || "").toLowerCase();
        if (!path) continue;
        for (var m = 0; m < MODULE_WATCH.length; m++) {
          if (path.indexOf(MODULE_WATCH[m]) !== -1) {
            out.push({ sev: FATAL, kind: "module", name: mods[i].name, path: mods[i].path });
            break;
          }
        }
      }
    } catch (e) {
      out.push({ sev: INFO, kind: "error", name: "modules", detail: "" + e });
    }

    // frida's own agent is injected by THIS loader, so its presence proves nothing. A second
    // copy of it is the interesting case - two agents means two sessions. Still only suspect:
    // a customer on an unusual frida build can end up with two module entries and no second
    // session at all, and that is not worth ending anyone's key over.
    var agents = 0;
    try {
      mods = Process.enumerateModules();
      for (i = 0; i < mods.length; i++) {
        if (String(mods[i].name || "").toLowerCase().indexOf("frida-agent") === 0) agents++;
      }
    } catch (e) { /* counted as zero, which is the safe direction */ }
    if (agents > 1) {
      out.push({ sev: SUSPECT, kind: "module", name: "frida-agent", path: String(agents) + " copies" });
    }

    try {
      procs = Process.enumerateProcesses();
      for (i = 0, n = procs.length; i < n; i++) {
        path = String(procs[i].path || "").toLowerCase();
        name = String(procs[i].name || "").toLowerCase();
        if (!name && !path) continue;
        var hay = name + " " + path;
        for (var p = 0; p < PROCESS_WATCH.length; p++) {
          if (hay.indexOf(PROCESS_WATCH[p]) !== -1) {
            out.push({ sev: FATAL, kind: "process", name: procs[i].name, path: procs[i].path });
            break;
          }
        }
      }
    } catch (e) {
      out.push({ sev: INFO, kind: "error", name: "processes", detail: "" + e });
    }

    return out;
  }

  function sessions() {
    var n = 1;
    try {
      var prev = JSON.parse(File.readAllText(LOCK));
      if (prev && prev.pid && prev.pid !== Process.id) n = prev.sessions ? prev.sessions + 1 : 2;
    } catch (e) { /* no usable lock, so we are the first */ }
    write(LOCK, JSON.stringify({ pid: Process.id, sessions: n, at: Date.now() }));
    return n;
  }

  function report() {
    var second = secondAgentHere();
    var findings = probe();
    if (second) {
      findings.push({ sev: SUSPECT, kind: "agent", name: "second gate in this process", path: "" });
    }
    var fatal = 0;
    for (var i = 0; i < findings.length; i++) {
      if (findings[i].sev === FATAL) fatal++;
    }
    var doc = {
      pid: Process.id,
      sessions: sessions(),
      fatal: fatal,
      findings: findings,
      at: new Date().toISOString(),
    };
    write(FINDINGS, JSON.stringify(doc));
    if (fatal) {
      say("[gate] " + fatal + " piece(s) of tooling on this machine - reported to support");
    } else if (findings.length) {
      say("[gate] " + findings.length + " note(s) about this machine sent to support");
    }
  }

  // fires once, at load, before anybody can arm the menu
  try {
    report();
  } catch (e) {
    say("[gate] the machine report failed: " + e);
  }

  function loadMenu() {
    var text;
    try {
      text = File.readAllText(PAYLOAD);
    } catch (e) {
      say("[gate] cannot read the payload: " + e);
      return false;
    }
    say("[gate] loading the holdable menu (" + text.length + " bytes)");
    var ok = true;
    try {
      // indirect eval: global scope, so the payload's top-level vars land on globalThis beside
      // Il2Cpp. A direct eval would trap them in this closure and the menu would come up empty.
      (0, eval)(text);
    } catch (e) {
      say("[gate] the menu threw at load: " + e);
      ok = false;
    }
    // drop our reference to the packed build. the payload's own decode loop has already run and
    // its plaintext string died with that loop's closure - this releases the 2.7 MB packed copy
    // so the only copy left in the process is the one the menu is actually running from.
    text = null;
    say(ok ? "[gate] holdable menu loaded" : "[gate] menu did not come up");
    return ok;
  }

  var polls = 0;
  say("[gate] bypass chain is live - bridge, bypass and quest hooks are installed");
  say("[gate] the holdable menu is NOT loaded yet");
  say("[gate] payload : " + PAYLOAD);
  say("[gate] waiting for enter in the loader window...");

  var timer = setInterval(function () {
    polls++;
    if (flag() !== ARM) {
      if (polls % 100 === 0) {
        say("[gate] still on standby after " + Math.round(polls * EVERY / 1000) + "s");
      }
      return;
    }
    clearInterval(timer);
    setFlag(DONE);
    loadMenu();
  }, EVERY);
})();
